mapper.select:
SELECT has_ad, COUNT(*) AS cnt
FROM bid_log
WHERE slot_code = #{slot}
  AND bid_at >= #{from}
  AND bid_at < #{to}
GROUP BY has_ad

EXPLAIN
SELECT has_ad, COUNT(*) AS cnt
FROM bid_log
WHERE slot_code = #{slot}
  AND bid_at >= #{from}
  AND bid_at < #{to}
GROUP BY has_ad

SELECT COUNT(*) AS deals,
       ROUND(SUM(pay_price), 2) AS amount,
       ROUND(SUM(pay_price) / COUNT(*), 2) AS avg_price
FROM bid_log
WHERE slot_code = #{slot}
  AND has_ad = 1
  AND bid_at >= #{from}
  AND bid_at < #{to}

EXPLAIN
SELECT COUNT(*) AS deals,
       ROUND(SUM(pay_price), 2) AS amount,
       ROUND(SUM(pay_price) / COUNT(*), 2) AS avg_price
FROM bid_log
WHERE slot_code = #{slot}
  AND has_ad = 1
  AND bid_at >= #{from}
  AND bid_at < #{to}

SELECT SUM(ad_cnt) AS deals,
       ROUND(SUM(total_pay_price), 2) AS amount,
       ROUND(SUM(total_pay_price) / SUM(ad_cnt), 2) AS avg_price
FROM bid_stat_hourly
WHERE slot_code = #{slot}
  AND stat_hour >= #{from}
  AND stat_hour < #{to}

EXPLAIN
SELECT SUM(ad_cnt) AS deals,
       ROUND(SUM(total_pay_price), 2) AS amount,
       ROUND(SUM(total_pay_price) / SUM(ad_cnt), 2) AS avg_price
FROM bid_stat_hourly
WHERE slot_code = #{slot}
  AND stat_hour >= #{from}
  AND stat_hour < #{to}

SELECT id, slot_code, has_ad, bid_at, request_id, cost_ms, pay_price
FROM bid_log
WHERE slot_code = #{slot}
ORDER BY bid_at DESC
LIMIT #{offset}, #{limit}

SELECT id, slot_code, has_ad, bid_at, request_id, cost_ms, pay_price
FROM bid_log
WHERE slot_code = #{slot}
  AND bid_at <= #{bidAt}
  AND (bid_at, has_ad, id) <= (#{bidAt}, #{hasAd}, #{lastId})
ORDER BY bid_at DESC, has_ad DESC, id DESC
LIMIT #{limit}

EXPLAIN
SELECT id, slot_code, has_ad, bid_at, request_id, cost_ms, pay_price
FROM bid_log
WHERE slot_code = #{slot}
ORDER BY bid_at DESC
LIMIT #{offset}, #{limit}

EXPLAIN
SELECT id, slot_code, has_ad, bid_at, request_id, cost_ms, pay_price
FROM bid_log
WHERE slot_code = #{slot}
  AND bid_at <= #{bidAt}
  AND (bid_at, has_ad, id) <= (#{bidAt}, #{hasAd}, #{lastId})
ORDER BY bid_at DESC, has_ad DESC, id DESC
LIMIT #{limit}
